@startuml

class Well {
  + code : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class OilCompany {
  + extractCrudeOil(well : Well, quantity : double) : void
}

class OnshoreWell {
  + surfaceExtension : double
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
}

class PollutionRate {
  + calculatePollutionRate(well : Well) : double
}

Well "1" -- "*" Company : extractedBy
OilCompany "1" -- "*" Company : is
OnshoreWell "1" -- "1" Well : is
OffshoreWell "1" -- "1" Well : is

@enduml

